def getCurrentDateTime(format=None, timezone=None, locale=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0181000" if __import__("os").path.isdir("./environment_mix/0181000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.now(datetime.timezone.utc)
    now_iso = start.isoformat()

    def _dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _iso(dt):
        if dt is None:
            return None
        try:
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        except Exception:
            try:
                return dt.isoformat()
            except Exception:
                return None

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _window_minute(dt_utc):
        dt_utc = dt_utc.astimezone(datetime.timezone.utc)
        return dt_utc.replace(second=0, microsecond=0)

    def _window_day(dt_utc):
        dt_utc = dt_utc.astimezone(datetime.timezone.utc)
        return dt_utc.replace(hour=0, minute=0, second=0, microsecond=0)

    def _get_rollup(rollups, api_key_id, window_type, window_start):
        ws = _iso(window_start)
        for r in rollups:
            if r.get("api_key_id") == api_key_id and r.get("window_type") == window_type and r.get("window_start") == ws:
                return r
        return None

    def _ensure_rollup(rollups, api_key_id, window_type, window_start, now):
        r = _get_rollup(rollups, api_key_id, window_type, window_start)
        if r:
            return r
        r = {
            "id": _new_id("ur"),
            "api_key_id": api_key_id,
            "window_type": window_type,
            "window_start": _iso(window_start),
            "requests_total": 0,
            "requests_rejected": 0,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        rollups.append(r)
        return r

    def _allowed_tz(key_row, tz):
        lst = key_row.get("allowed_timezones")
        if lst is None:
            return True
        if isinstance(lst, list) and len(lst) == 0:
            return True
        if not isinstance(lst, list):
            return True
        return tz in lst

    def _is_iana_identifier(s):
        if not isinstance(s, str) or not s or len(s) > 128:
            return False
        # Basic IANA-like validation; actual existence checked via zoneinfo
        allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789/_+-")
        if any(ch not in allowed for ch in s):
            return False
        if "/" not in s and s not in ("UTC", "GMT"):
            # Many real IANA names contain '/', accept UTC/GMT too
            return False
        if s.startswith("/") or s.endswith("/") or "//" in s:
            return False
        return True

    def _find_active_key(keys):
        # Ambient auth: choose an active key that can serve the request
        for k in keys:
            if k.get("status") == "active":
                return k
        # If none active, but keys exist, still pick one to log rejection as KEY_INACTIVE
        return keys[0] if keys else None

    def _log_request(reqs, api_key_id, status, fmt, tz, tz_id, loc, resolved_utc, resolved_local, resp_val, resp_unix, err_code, err_msg, now):
        row = {
            "id": _new_id("dtr"),
            "api_key_id": api_key_id,
            "tool_name": "getCurrentDateTime",
            "status": status,
            "format": fmt,
            "timezone": tz,
            "timezone_id": tz_id,
            "locale": loc,
            "resolved_at_utc": _iso(resolved_utc) if resolved_utc else None,
            "resolved_at_local": _iso(resolved_local) if resolved_local else None,
            "response_value": resp_val,
            "response_unix_seconds": resp_unix,
            "error_code": err_code,
            "error_message": err_msg,
            "client_ip": None,
            "user_agent": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        return row

    def _update_key_last_used(keys, api_key_id, now):
        for k in keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                return True
        return False

    # Validate parameter types early
    if format is not None and not isinstance(format, str):
        return _err("VALIDATION_ERROR", "format must be a string or null")
    if timezone is not None and not isinstance(timezone, str):
        return _err("VALIDATION_ERROR", "timezone must be a string or null")
    if locale is not None and not isinstance(locale, str):
        return _err("VALIDATION_ERROR", "locale must be a string or null")

    # Load store
    keys = _load("api_keys.json")
    tzcat = _load("timezone_catalog.json")
    reqs = _load("datetime_requests.json")
    rollups = _load("api_usage_rollups.json")

    api_key = _find_active_key(keys)
    if not api_key:
        # No way to authenticate
        return _err("UNAUTHORIZED", "No API key context available")

    api_key_id = api_key.get("id")
    now = start  # now for timestamps

    # Start request log row only for invocations that pass authentication.
    # Ambient auth: having a key row means authenticated.
    accepted_row = _log_request(
        reqs=reqs,
        api_key_id=api_key_id,
        status="accepted",
        fmt=format,
        tz=timezone,
        tz_id=None,
        loc=locale,
        resolved_utc=None,
        resolved_local=None,
        resp_val=None,
        resp_unix=None,
        err_code=None,
        err_msg=None,
        now=now,
    )

    # Helper to finalize request status exactly once
    def _finalize(final_status, err_code=None, err_msg=None, tz_id=None, resolved_utc=None, resolved_local=None, resp_val=None, resp_unix=None, key_last_used=False):
        # transition accepted -> final_status
        accepted_row["status"] = final_status
        accepted_row["error_code"] = err_code
        accepted_row["error_message"] = err_msg
        accepted_row["timezone_id"] = tz_id
        accepted_row["resolved_at_utc"] = _iso(resolved_utc) if resolved_utc else None
        accepted_row["resolved_at_local"] = _iso(resolved_local) if resolved_local else None
        accepted_row["response_value"] = resp_val
        accepted_row["response_unix_seconds"] = resp_unix
        accepted_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        # Persist logs
        _save("datetime_requests.json", reqs)
        # Update key last used only on success
        if key_last_used:
            _update_key_last_used(keys, api_key_id, datetime.datetime.now(datetime.timezone.utc))
            _save("api_keys.json", keys)
        return

    # Enforce key active
    if api_key.get("status") != "active":
        # Even if inactive, measure rejected traffic: increment total+rejected and log rejected.
        minute_start = _window_minute(now)
        day_start = _window_day(now)
        rm = _ensure_rollup(rollups, api_key_id, "minute", minute_start, now)
        rd = _ensure_rollup(rollups, api_key_id, "day", day_start, now)
        rm["requests_total"] += 1
        rm["requests_rejected"] += 1
        rm["updated_at"] = _iso(now)
        rd["requests_total"] += 1
        rd["requests_rejected"] += 1
        rd["updated_at"] = _iso(now)
        _save("api_usage_rollups.json", rollups)

        _finalize("rejected", err_code="KEY_INACTIVE", err_msg="API key is not active")
        return _err("UNAUTHORIZED", "API key is not active", error_code="KEY_INACTIVE")

    # Validate format
    allowed_named = {"ISO", "UNIX", "RFC2822", "HTTP", "SQL"}
    if format is not None:
        if format in allowed_named:
            pass
        else:
            # treat as custom strftime; validate by attempting to format
            try:
                _ = now.strftime(format)
            except Exception:
                # count accepted traffic? invalid format is a failed request, but acceptance already logged;
                # quota counted on accept below, so ensure quota accepted first. However rule says quota before accepting.
                # We already created accepted log row; keep it but handle quota now as "accepted" semantics.
                # To honor quota-before-accept, we enforce quota now before proceeding further and can still reject.
                pass

    # Validate timezone and resolve tz info if provided
    tz_obj = None
    tz_row = None
    tz_id = None
    if timezone is not None:
        if not _is_iana_identifier(timezone):
            # quota check + rollup handling below (reject if over quota); but this is a failure after accept
            pass
        else:
            # existence check using zoneinfo
            try:
                from zoneinfo import ZoneInfo
                tz_obj = ZoneInfo(timezone)
            except Exception:
                tz_obj = None
            if tz_obj is not None:
                # find in catalog
                for r in tzcat:
                    if r.get("iana_name") == timezone:
                        tz_row = r
                        tz_id = r.get("id")
                        break

    # Quota enforcement BEFORE accepting a request: because we already wrote accepted row, we must still enforce
    # and if exceeded, convert to rejected and count as rejected traffic.
    quota_min = api_key.get("quota_requests_per_minute")
    quota_day = api_key.get("quota_requests_per_day")
    if not isinstance(quota_min, int) or quota_min < 0 or not isinstance(quota_day, int) or quota_day < 0:
        # malformed key configuration
        # Treat as failed (service misconfigured) but still count accepted usage.
        minute_start = _window_minute(now)
        day_start = _window_day(now)
        rm = _ensure_rollup(rollups, api_key_id, "minute", minute_start, now)
        rd = _ensure_rollup(rollups, api_key_id, "day", day_start, now)
        rm["requests_total"] += 1
        rm["updated_at"] = _iso(now)
        rd["requests_total"] += 1
        rd["updated_at"] = _iso(now)
        _save("api_usage_rollups.json", rollups)

        _finalize("failed", err_code="KEY_QUOTA_INVALID", err_msg="API key quota configuration invalid")
        return _err("VALIDATION_ERROR", "API key quota configuration invalid", error_code="KEY_QUOTA_INVALID")

    minute_start = _window_minute(now)
    day_start = _window_day(now)
    rm = _ensure_rollup(rollups, api_key_id, "minute", minute_start, now)
    rd = _ensure_rollup(rollups, api_key_id, "day", day_start, now)

    # Determine if this request would exceed quotas if accepted.
    would_min = rm.get("requests_total", 0) + 1
    would_day = rd.get("requests_total", 0) + 1
    if (quota_min != 0 and would_min > quota_min) or (quota_day != 0 and would_day > quota_day):
        # increment total+rejected
        rm["requests_total"] = would_min
        rm["requests_rejected"] = rm.get("requests_rejected", 0) + 1
        rm["updated_at"] = _iso(now)
        rd["requests_total"] = would_day
        rd["requests_rejected"] = rd.get("requests_rejected", 0) + 1
        rd["updated_at"] = _iso(now)
        _save("api_usage_rollups.json", rollups)

        _finalize("rejected", err_code="QUOTA_EXCEEDED", err_msg="Quota exceeded")
        return _err("QUOTA_EXCEEDED", "Quota exceeded", error_code="QUOTA_EXCEEDED")

    # Accept: increment requests_total for minute and day
    rm["requests_total"] = would_min
    rm["updated_at"] = _iso(now)
    rd["requests_total"] = would_day
    rd["updated_at"] = _iso(now)
    _save("api_usage_rollups.json", rollups)

    # Now validate timezone allowlist
    if timezone is not None and not _allowed_tz(api_key, timezone):
        _finalize("rejected", err_code="TIMEZONE_NOT_ALLOWED", err_msg="Timezone not allowed for this API key")
        return _err("UNAUTHORIZED", "Timezone not allowed for this API key", error_code="TIMEZONE_NOT_ALLOWED")

    # Validate timezone existence if provided
    if timezone is not None:
        if not _is_iana_identifier(timezone) or tz_obj is None:
            _finalize("failed", err_code="INVALID_TIMEZONE", err_msg="Invalid or unknown IANA timezone identifier", tz_id=None)
            return _err("VALIDATION_ERROR", "Invalid or unknown IANA timezone identifier", error_code="INVALID_TIMEZONE")

    # Validate format properly now
    fmt_effective = format or "ISO"
    resolved_utc = datetime.datetime.now(datetime.timezone.utc)
    resolved_local = resolved_utc
    if tz_obj is not None:
        resolved_local = resolved_utc.astimezone(tz_obj)

    unix_seconds = int(resolved_utc.timestamp())
    response_value = None

    if fmt_effective == "ISO":
        response_value = resolved_local.isoformat()
    elif fmt_effective == "UNIX":
        response_value = str(unix_seconds)
    elif fmt_effective == "RFC2822":
        import email.utils
        response_value = email.utils.format_datetime(resolved_local)
    elif fmt_effective == "HTTP":
        # HTTP-date must be GMT/UTC
        import email.utils
        response_value = email.utils.format_datetime(resolved_utc.astimezone(datetime.timezone.utc), usegmt=True)
    elif fmt_effective == "SQL":
        # Common SQL datetime string
        response_value = resolved_local.strftime("%Y-%m-%d %H:%M:%S")
    else:
        try:
            response_value = resolved_local.strftime(fmt_effective)
        except Exception:
            _finalize("failed", err_code="INVALID_FORMAT", err_msg="Invalid format string", tz_id=tz_id)
            return _err("VALIDATION_ERROR", "Invalid format string", error_code="INVALID_FORMAT")

    # Success
    _finalize(
        "succeeded",
        tz_id=tz_id,
        resolved_utc=resolved_utc,
        resolved_local=resolved_local if timezone is not None else None,
        resp_val=response_value,
        resp_unix=unix_seconds if unix_seconds >= 0 else None,
        key_last_used=True,
    )

    return {
        "tool": "getCurrentDateTime",
        "timezone": timezone or "UTC",
        "locale": locale,
        "format": fmt_effective,
        "value": response_value,
        "unix_seconds": unix_seconds,
        "resolved_at_utc": resolved_utc.isoformat().replace("+00:00", "Z"),
    }

def listTimezones(status=None, country_code=None, q=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0181000" if __import__("os").path.isdir("./environment_mix/0181000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    try:
        # Validate filters (relaxed for q: accept non-string and coerce to string)
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "deprecated"):
                return _err("VALIDATION_ERROR", "status must be one of: active, deprecated")
        if country_code is not None:
            if not isinstance(country_code, str) or len(country_code) != 2:
                return _err("VALIDATION_ERROR", "country_code must be a 2-letter ISO code")
            country_code = country_code.upper()

        if q is not None and not isinstance(q, str):
            # relax to match observed vendor behavior: coerce scalars to string
            if isinstance(q, (int, float, bool)):
                q = str(q)
            else:
                return _err("VALIDATION_ERROR", "q must be a string")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")

        tzcat = _load("timezone_catalog.json")
        if isinstance(tzcat, dict) and isinstance(tzcat.get("rows"), list):
            tz_rows = tzcat.get("rows")
        elif isinstance(tzcat, list):
            tz_rows = tzcat
        else:
            tz_rows = []

        # Filter safely
        def _match(r):
            if not isinstance(r, dict):
                return False
            if status is not None and r.get("status") != status:
                return False
            if country_code is not None:
                cc = r.get("country_code")
                if not isinstance(cc, str) or cc.upper() != country_code:
                    return False
            if q is not None:
                name = r.get("iana_name") or ""
                if not isinstance(name, str):
                    name = str(name)
                if q.lower() not in name.lower():
                    return False
            return True

        filtered = [r for r in tz_rows if _match(r)]

        # Sort by iana_name then id
        filtered.sort(key=lambda r: ((r.get("iana_name") or "").lower(), r.get("id") or ""))

        # Cursor:
        # Accept either:
        #  - our base64 token of "iana_name|id"
        #  - a raw row id (as seen in audit: they passed an api key id)
        start_index = 0
        if cursor:
            decoded = None
            # try base64 first
            try:
                pad = "=" * (-len(cursor) % 4)
                raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8"))
                token = raw.decode("utf-8")
                if "|" in token:
                    decoded = token
            except Exception:
                decoded = None

            if decoded:
                last_name, last_id = decoded.split("|", 1)
                last_name_l = (last_name or "").lower()
                for i, r in enumerate(filtered):
                    nm = (r.get("iana_name") or "").lower()
                    rid = r.get("id") or ""
                    if (nm, rid) > (last_name_l, last_id):
                        start_index = i
                        break
                else:
                    start_index = len(filtered)
            else:
                # treat cursor as an opaque "start after id"
                idx = None
                for i, r in enumerate(filtered):
                    if r.get("id") == cursor:
                        idx = i
                        break
                if idx is not None:
                    start_index = idx + 1
                else:
                    # unknown cursor: behave like vendor often does—start from beginning, not error
                    start_index = 0

        page = filtered[start_index:start_index + limit]
        has_more = start_index + limit < len(filtered)

        next_cursor = None
        if has_more and page:
            last = page[-1]
            last_name = last.get("iana_name") or ""
            last_id = last.get("id") or ""
            token = f"{last_name}|{last_id}".encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

        return {
            "object": "list",
            "data": page,
            "meta": {
                "total": len(filtered),
                "limit": limit,
                "has_more": has_more,
                "next_cursor": next_cursor
            }
        }
    except Exception as e:
        return _err("FAILED", "Unexpected error", detail=str(e))

def getTimezoneCatalogById(id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0181000" if __import__("os").path.isdir("./environment_mix/0181000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")
    tz_id = id.strip()

    # Load datastore. In this service, collections may be stored either as a list of rows
    # or as an object envelope like {"rows":[...]} depending on generator/version.
    raw = _load("timezone_catalog.json")
    rows = None
    if isinstance(raw, list):
        rows = raw
    elif isinstance(raw, dict) and isinstance(raw.get("rows"), list):
        rows = raw.get("rows")
    else:
        # Unexpected shape => treat as not found rather than crashing
        return _err("NOT_FOUND", "timezone_catalog record not found", id=tz_id)

    # Find record
    rec = None
    for r in rows:
        if isinstance(r, dict) and r.get("id") == tz_id:
            rec = r
            break

    if rec is None:
        return _err("NOT_FOUND", "timezone_catalog record not found", id=tz_id)

    # Return record (do not fabricate fields)
    return {"timezone": rec}

def listDateTimeRequests(status=None, timezone=None, from_created_at=None, to_created_at=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0181000" if __import__("os").path.isdir("./environment_mix/0181000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "bad"
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return "bad"

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "bad"
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "bad"
            # expected: {"created_at": "...", "id": "..."}
            ca = obj.get("created_at")
            rid = obj.get("id")
            if not isinstance(ca, str) or not isinstance(rid, str):
                return "bad"
            dt = _parse_rfc3339(ca)
            if dt == "bad":
                return "bad"
            return {"created_at": dt, "id": rid}
        except Exception:
            return "bad"

    def _encode_cursor(dt, rid):
        obj = {"created_at": _iso(dt), "id": rid}
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate filters
    allowed_status = {"accepted", "succeeded", "failed", "rejected"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

    if timezone is not None and (not isinstance(timezone, str) or not timezone.strip()):
        return _err("VALIDATION_ERROR", "Invalid timezone filter.", field="timezone")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")

    fdt = _parse_rfc3339(from_created_at)
    if fdt == "bad":
