def rotateApiKey(confirm, **_extra):
    import json, os, datetime, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0181000" if __import__("os").path.isdir("./environment_mix/0181000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(confirm, bool):
        return _err("VALIDATION_ERROR", "confirm must be a boolean.", field="confirm")
    if confirm is not True:
        return _err("VALIDATION_ERROR", "Key rotation requires confirm=true.", field="confirm")

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    # Ambient auth: pick an active key to rotate (caller is authenticated for "current" key).
    # If multiple active keys exist, rotate the most recently used (or most recently updated).
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            s2 = s.strip()
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active:
        return _err("UNAUTHORIZED", "No active API key available to rotate.")

    def _rank(k):
        lu = _parse_dt(k.get("last_used_at"))
        up = _parse_dt(k.get("updated_at"))
        ca = _parse_dt(k.get("created_at"))
        return (lu or up or ca or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))

    active.sort(key=_rank, reverse=True)
    key_row = active[0]

    if key_row.get("status") != "active":
        return _err("INVALID_TRANSITION", "API key must be active to rotate.", current_status=key_row.get("status"))

    # Generate new secret; store only hash, and update prefix.
    # Ensure unique(key_hash) and unique(key_prefix) and length constraints.
    def _gen_secret():
        # keep it reasonably long; vendor-like token
        return "dt_" + secrets.token_urlsafe(32)

    def _hash_secret(secret):
        # Store deterministic hash material; plaintext never stored.
        return hashlib.sha256(secret.encode("utf-8")).hexdigest()

    def _prefix_for(secret):
        # key_prefix length 6..16
        base = secret.replace("-", "").replace("_", "")
        if len(base) < 6:
            base = (base + "000000")[:6]
        return base[:10]

    existing_hashes = {k.get("key_hash") for k in api_keys if isinstance(k, dict) and isinstance(k.get("key_hash"), str)}
    existing_prefixes = {k.get("key_prefix") for k in api_keys if isinstance(k, dict) and isinstance(k.get("key_prefix"), str)}

    secret = _gen_secret()
    key_hash = _hash_secret(secret)
    key_prefix = _prefix_for(secret)

    # Avoid collisions
    attempts = 0
    while (key_hash in existing_hashes or key_prefix in existing_prefixes or not (6 <= len(key_prefix) <= 16)) and attempts < 50:
        secret = _gen_secret()
        key_hash = _hash_secret(secret)
        key_prefix = _prefix_for(secret)
        attempts += 1
    if key_hash in existing_hashes or key_prefix in existing_prefixes or not (6 <= len(key_prefix) <= 16):
        return _err("CONFLICT", "Unable to rotate key due to uniqueness constraints. Please retry.")

    now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # Mutate the existing record (invalidate prior secret immediately by overwriting hash/prefix)
    key_row["key_hash"] = key_hash
    key_row["key_prefix"] = key_prefix
    key_row["updated_at"] = _iso(now)
    key_row["last_used_at"] = _iso(now)

    _save("api_keys.json", api_keys)

    return {
        "data": {
            "api_key_id": key_row["id"],
            "display_name": key_row.get("display_name"),
            "status": key_row.get("status"),
            "key_prefix": key_row.get("key_prefix"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "new_api_key_secret": secret,
        }
    }
